import { bearerFetchPlugin } from "./bearer";
import type { TokenStore } from "./browser-storage";
import type { AuthFetch } from "./exchange";

export type ManagedProvider = "google" | "apple" | "microsoft";

export interface SignInOptions {
  provider: ManagedProvider;
}

export interface ManagedAuthError {
  code: string;
  message: string;
}

export interface SignInResult {
  data: { success: boolean } | null;
  error: ManagedAuthError | null;
}

/** The per-platform transport pair; everything else about the plugin is identical. */
export interface ManagedAuthFlows {
  signIn(options: SignInOptions): Promise<SignInResult>;
  handleRedirect(): Promise<SignInResult | undefined>;
}

export interface FlowContext {
  $fetch: AuthFetch;
  storage: TokenStore;
}

/** The slice of Better Auth's reactive store the plugin needs (named in the emitted plugin type). */
export interface SessionStore {
  notify(signal: string): void;
}

/**
 * Assembles the Better Auth client plugin around a platform transport: bearer attachment from
 * `storage`, the `managedAuth` action surface, and the reactive-session refresh after a successful
 * sign-in (`$fetch("/get-session")` + notify), so `useSession()` updates without a reload.
 */
export const managedAuthPlugin = (
  storage: TokenStore,
  createFlows: (context: FlowContext) => ManagedAuthFlows,
) => ({
  id: "runable-managed-auth",
  fetchPlugins: [bearerFetchPlugin(storage)],
  getActions: ($fetch: AuthFetch, $store: SessionStore) => {
    const flows = createFlows({ $fetch, storage });
    const refreshed = async <Result extends SignInResult | undefined>(result: Result) => {
      if (result?.data?.success) {
        await $fetch("/get-session");
        $store.notify("$sessionSignal");
      }
      return result;
    };
    return {
      managedAuth: {
        signIn: async (options: SignInOptions) => refreshed(await flows.signIn(options)),
        handleRedirect: async () => refreshed(await flows.handleRedirect()),
        getToken: () => storage.getToken(),
        clearToken: () => storage.clearToken(),
      },
    };
  },
});
